  auto d = std::make_unique<amdgpu::VectorMemState>(amdgpu::GLOBAL_MEM);
  d->elem_size = 1;
  d->num_elems = 1;
  d->is_load = true;
  d->wait_counter_type = amdgpu::WaitCounterType::ASYNCCNT;
  d->lds_dst = true;
