void ClusterLoadAsyncToLdsB8Vglobal::execute_impl(amdgpu::Wavefront &wf) {
  auto d = std::make_unique<amdgpu::VectorMemState>(amdgpu::GLOBAL_MEM);
  d->elem_size = 1;
  d->num_elems = 1;
  d->is_load = true;
  d->wait_counter_type = amdgpu::WaitCounterType::ASYNCCNT;
  d->lds_dst = true;
  d->lds_per_lane_addr = true;
  d->lds_base = wf.lds_base();
  d->cluster_multicast = true;
  d->cluster_mcast_mask = wf.m0() & amdgpu::kClusterMulticastMask;
  d->request_force_l1_bypass = true;
  d->mtype = amdgpu::mtype_from_flags_gfx12(inst_.scope, inst_.th);
  d->non_temporal = 0;
  flat_calculate_addresses(inst_, wf, *d);
  auto &cu = wf.cu();
  uint64_t exec = wf.exec();
  // CDNA5 ISA 10.8.1 and expressions 95-102 and 106-109 add IOFFSET to global and LDS addresses.
  uint32_t lds_addr_base =
      wf.vgpr_alloc().base +
      *Isa::resolved_vgpr_offset(wf, vdst.opr_type_, vdst.encoding_value_, vdst.vgpr_msb_role());
  for (uint32_t lane = 0; lane < wf.wf_size(); ++lane) {
    if (!(exec & (1ULL << lane)))
      continue;
    uint32_t lane_lds_addr = amdgpu::RegisterAccess(cu).read_vgpr(lds_addr_base, lane);
    d->per_lane_lds_addr[lane] = async_lds_lane_address(inst_, wf, lane_lds_addr, 1);
  }
  set_data(std::move(d));
}

